//!Main435c3e submits BUILD/production before5a240 UNIT callbacks.41d110's
//!FLAG pass follows UNITs and AI at435d32; it observes their ownership writes.
use crate::{Game,json,Value,original_flag_display as flag};
use super::{Record,FlagSeed,game::plain};
use std::collections::BTreeSet;
impl Game{
 fn display_flag_colors(&self,seeds:&[FlagSeed])->Vec<([i16;2],u8)>{seeds.iter().map(|f|(f.position,self.sectors.iter().find(|s|s.id==f.sector).map_or(4,|s|if s.owner<0{4}else{s.owner as u8}))).collect()}
 fn fallback_display_flag_seeds(&self)->Vec<FlagSeed>{self.native_display_objects().into_iter().filter_map(|o|Some(FlagSeed{sector:o.flag?,position:o.position})).collect()}
 ///41d280's CP order/positions are initialized independently of OBJECT
 ///lifetimes. Neutral flags still exist if their associated OBJECT retires.
 pub(crate) fn initialize_native_scene_display(&mut self,v:&Value){
  if !self.map.original{return;}let mut forts=self.buildings.iter().filter(|b|b.kind=="fort").map(|b|(b.raw_base.map(|p|[p.0 as i16,p.1 as i16]).unwrap_or([(b.x/2.)as i16,(b.y/2.)as i16]),b.sector)).collect::<Vec<_>>();forts.sort_by_key(|(p,_)|(p[1],p[0]));let excluded=forts.iter().take(2).map(|(p,id)|self.world_sector(*p).unwrap_or(*id)).collect::<BTreeSet<_>>();
  let mut raw=v["sectors"].as_array().into_iter().flatten().filter(|s|s["nativeSlot"].as_u64().is_some_and(|n|n<64)&&s["rawFlagTile"].as_array().is_some_and(|p|p.len()==2)&&s["countsForProduction"]!=false&&!s["id"].as_u64().is_some_and(|id|excluded.contains(&(id as usize)))).collect::<Vec<_>>();raw.sort_by_key(|s|s["nativeSlot"].as_u64());
  self.native_display.flag_seeds=raw.into_iter().filter_map(|s|Some(FlagSeed{sector:s["id"].as_u64()?as usize,position:[(s["rawFlagTile"][0].as_i64()?as i8 as i16).wrapping_shl(4),(s["rawFlagTile"][1].as_i64()?as i8 as i16).wrapping_shl(4)]})).collect();self.native_display.flags_initialized=true;self.native_display.flags_before=None;self.native_display.radar_before=None;self.rebuild_native_scene_flags();
 }
 ///44ea30 calls41d280 after writing the new CP owner. It rebuilds ALL
 ///flag colors and clears every active transition byte, without changing
 ///the records of any already completed41d110 pass. During normal Main,
 ///the current UNIT's capture is therefore visible to the later FLAG pass.
 pub(crate) fn rebuild_native_scene_flags(&mut self){if !self.map.original{return;}if !self.native_display.flags_initialized{self.native_display.flag_seeds=self.fallback_display_flag_seeds();self.native_display.flags_initialized=true;}let seeds=self.display_flag_colors(&self.native_display.flag_seeds);self.native_display.flags.rebuild(&seeds);}
 fn native_flag_view(&self)->flag::View{let(camera,size)=self.native_view.unwrap_or(([0,0],[(self.map.width*16)as i16,(self.map.height*16)as i16]));flag::View{camera,size,frame:self.native_flag_frame,mode:self.native_feedback.scene_gate,forts:self.native_fort_bases().map(|f|f.map(Some)).unwrap_or([None,None]),fort_visible:[self.native_display.fort_visible[0],self.native_display.fort_visible[1]]}}
 fn flag_rows(pool:&mut flag::Pool,view:flag::View,seeds:&[FlagSeed])->Vec<(Record,Value)>{let mut out=Vec::new();pool.submit(view,|record,kind,slot|{let source=["flag","flagShadow","fortBanner","fortBannerShadow"][usize::from(kind)];let id=if kind<2{seeds.get(slot).map_or(slot,|s|s.sector)}else{slot};let mut row=plain(record,source,id);row["nativeSlot"]=json!(slot);out.push((record,row));});out}
 pub(crate) fn project_native_flag_display(&self)->Vec<(Record,Value)>{let mut pool=self.native_display.flags.clone();let seeds=if self.native_display.flags_initialized{self.native_display.flag_seeds.clone()}else{let seeds=self.fallback_display_flag_seeds();pool.rebuild(&self.display_flag_colors(&seeds));seeds};Self::flag_rows(&mut pool,self.native_flag_view(),&seeds)}
 pub(crate) fn capture_native_flag_display(&mut self){if !self.native_display.flags_initialized{self.rebuild_native_scene_flags();}let view=self.native_flag_view();let rows=Self::flag_rows(&mut self.native_display.flags,view,&self.native_display.flag_seeds);self.native_display.flags_before=Some(rows);}
 fn radar_rows(values:Vec<(usize,Option<usize>,crate::original_building_display::Result)>)->Vec<(Record,Value)>{values.into_iter().filter_map(|(slot,id,result)|{let record=result.record?;let mut row=plain(record,"radarDish",id.unwrap_or(65536+slot));row["nativeSlot"]=json!(slot);Some((record,row))}).collect()}
 pub(crate) fn project_native_radar_display(&self)->Vec<(Record,Value)>{Self::radar_rows(self.native_radar_display_projection())}
 ///Only artwork inputs are retained: no complete BUILD, production queue,
 ///contact binding or mutable factory state is duplicated.
 pub(crate) fn project_native_building_display(&self)->Vec<Value>{let radar=self.native_radar_building_ids();self.native_factory_draw_order().into_iter().filter_map(|id|self.native_building_display_row(id,radar.contains(&id))).collect()}
 fn native_building_display_row(&self,id:usize,radar:bool)->Option<Value>{let b=self.buildings.iter().find(|b|b.id==id)?;Some(json!({"kind":"building","stage":"pre","id":id,"time":self.time,"seconds":self.remaining_seconds(b),"radarDishQueued":radar,"art":{"id":id,"kind":b.kind,"team":b.team,"x":b.x,"y":b.y,"w":b.w,"h":b.h,"hp":b.hp,"maxHp":b.max_hp,"stars":b.stars,"product":b.product,"progress":b.progress,"completionTicks":b.completion_ticks,"rawBase":b.raw_base,"orientation":b.orientation,"nativeFortDestroyed":b.kind=="fort"&&b.hp<0.,"nativeWorkshopDrawQueued":self.native_workshop_draw_queued(id),"nativeFlagFrame":self.native_flag_frame}}))}
 ///40ad60 invokes the per-BUILD radar caller before UNIT callbacks. Capture
 ///the old dish frame, then retain its advanced word0A for the next call.
 pub(crate) fn capture_native_building_display(&mut self){if !self.map.original{return;}self.prepare_native_workshop_rates();let radar=self.native_radar_building_ids();let mut rows=Vec::new();let mut dishes=Vec::new();for id in self.native_factory_draw_order(){let Some(index)=self.buildings.iter().position(|b|b.id==id)else{continue;};self.prepare_native_factory_draw(index);if let Some(row)=self.native_building_display_row(id,radar.contains(&id)){rows.push(row);}rows.extend(self.native_workshop_building_callback_by_id(id));let values=self.advance_native_radar_display_for(id);dishes.extend(Self::radar_rows(values));self.finish_native_factory_draw(index);self.native_building_fragment_tail(id);}self.native_display.buildings_before=Some(rows);self.native_display.radar_before=Some(dishes);}
 ///Renderer visibility is separate from team activity and fort HP.
 pub(crate) fn set_native_display_fort_state(&mut self,owner:usize,value:u8){if let Some(f)=self.native_display.fort_visible.get_mut(owner){*f=value;}}
 ///The separate native cutscene controller owns622cc0. Ordinary battles
 ///retain0;1..15 draw only fort banners,>=16 omit the complete flag pass.
 pub(crate) fn set_native_display_scene_mode(&mut self,mode:i32){self.native_feedback.scene_gate=mode;}
}
