 fn metadata(word:i16,notice:u8)->Value{json!({"nativeWorldBuildings":(0..35).map(|slot|json!({"nativeSlot":slot,"kind":if slot==0{8}else{-1},"x":300,"y":200,"hp":100,"maxHp":100,"flags6":255,"nativeWord0A":word,"nativeByte15":notice,"buildingId":if slot==0{Some(77)}else{None}})).collect::<Vec<_>>(),"sectors":[{"id":0,"nativeSlot":0,"rawFlagTile":[20,21]}]})}
